(function() local r=comp:GetPrefs("Comp.FrameFormat.Rate") local t=(time-comp.RenderStart)/r local T=(comp.RenderEnd-comp.RenderStart)/r local ti=t-UIT_Ctrl.InDelay local a=1 if ti>=0 then local p=math.min(1,ti/math.max(UIT_Ctrl.InDur,0.001)) local g=UIT_Ctrl.Engine local e=p if g<0.5 then e=1-(1-p)^3 elseif g<1.5 then local k=math.max(UIT_Ctrl.Stiff,1) local w=math.sqrt(k) local z=math.min(0.999,math.max(0.05,UIT_Ctrl.Damp/(2*w))) local wd=w*math.sqrt(1-z*z) e=1-math.exp(-z*w*ti)*(math.cos(wd*ti)+z*w/wd*math.sin(wd*ti)) elseif g<2.5 then local q=p if q<0.3636 then e=7.5625*q*q elseif q<0.7273 then q=q-0.5454 e=7.5625*q*q+0.75 elseif q<0.9091 then q=q-0.8182 e=7.5625*q*q+0.9375 else q=q-0.9545 e=7.5625*q*q+0.984375 end elseif g<3.5 then if p>0 and p<1 then e=2^(-10*p)*math.sin((p-0.075)*20.944)+1 end elseif g<4.5 then local q=p-1 e=1+(UIT_Ctrl.Over+1)*q*q*q+UIT_Ctrl.Over*q*q else e=(1-math.exp(-4*p))/(1-math.exp(-4)) end a=1-e end if UIT_Ctrl.HasOut>0.5 then local po=math.min(1,math.max(0,(t-(T-UIT_Ctrl.OutOffset-UIT_Ctrl.OutDur-(select(2, string.gsub(UIT_Ctrl.Text.Value, "%S+", ""))-1)*UIT_Ctrl.Stagger))/math.max(UIT_Ctrl.OutDur,0.001))) a=math.min(1,a+po*po*(3-2*po)) end return a end)()